import { test, expect, setThemePlan } from "../helpers/theme-browser";

for (const plan of ["FREE", "PAID"] as const) {
  test(`pricing identifies the signed-in ${plan} plan using verified access`, async ({
    page,
    themeUser,
  }) => {
    await setThemePlan(themeUser, plan);
    await page.goto("/pricing");
    const current = page.getByRole("article", {
      name: plan === "PAID" ? "Premium plan" : "Free plan",
      exact: true,
    });
    await expect(
      current.getByRole("button", { name: "Current plan", exact: true }),
    ).toBeDisabled();
    await expect(current.locator("[data-plan-badge]")).toHaveText("Current plan");
    await expect(
      page.getByRole("button", { name: "Start free", exact: true }),
    ).toHaveCount(0);
    if (plan === "FREE") {
      await expect(
        page.getByRole("button", { name: "Upgrade to Premium" }),
      ).toBeEnabled();
      for (const name of ["Chalk Premium Light", "Obsidian Premium Dark"]) {
        await page.getByRole("button", { name: "Choose appearance" }).click();
        await page.getByRole("menuitemradio", { name, exact: true }).click();
        const dialog = page.getByRole("dialog", {
          name: "Upgrade to Premium",
          exact: true,
        });
        await expect(dialog).toBeVisible();
        await expect(
          dialog.locator('[data-highlighted="true"]'),
        ).toHaveAttribute("data-upgrade-feature", "themes");
        await page.keyboard.press("Escape");
      }
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await page
        .getByRole("menuitemradio", { name: "Nightbloom Dark", exact: true })
        .click();
      await page.reload();
      await expect(page.locator("html")).toHaveAttribute("data-theme", "dark");
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        "purple",
      );
    } else {
      await expect(
        page.getByRole("button", { name: "Upgrade to Premium" }),
      ).toHaveCount(0);
      await expect(
        page.getByRole("link", { name: "Open workspace" }),
      ).toHaveAttribute("href", "/compose");
      for (const [name, theme] of [
        ["Lavender Light", "light"],
        ["Nightbloom Dark", "dark"],
        ["Chalk Light", "light"],
        ["Obsidian Dark", "dark"],
      ]) {
        await page.getByRole("button", { name: "Choose appearance" }).click();
        await page.getByRole("menuitemradio", { name, exact: true }).click();
        await expect(page.locator("html")).toHaveAttribute(
          "data-appearance",
          name.startsWith("Chalk") || name.startsWith("Obsidian")
            ? "vercel"
            : "purple",
        );
        await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
        await page.screenshot({
          path: test
            .info()
            .outputPath(`pricing-premium-${name.split(" ")[0]}.png`),
          fullPage: true,
        });
        // The original pricing header and workspace reuse the same appearance control.
        await page.goto("/usage");
        await expect(
          page.getByRole("button", { name: "Choose appearance" }),
        ).toBeVisible();
        await expect(page.locator("html")).toHaveAttribute("data-theme", theme);
        await page.goto("/pricing");
        await expect(
          page.locator(".pricing-nav .appearance-control"),
        ).toBeVisible();
      }
    }
  });
}
